def replace(tokens, pair, identity):
    result = []
    index = 0
    while index < len(tokens):
        if tuple(tokens[index : index + 2]) == pair:
            result.append(identity)
            index += 2
        else:
            result.append(tokens[index])
            index += 1
    return result

